from typing import Dict

def prime_factors(n: int) -> Dict[int, int]:
    """Return the prime factorization of n.

    Args:
        n: A positive integer.

    Returns:
        A dict of {prime: exponent}. Empty when n == 1.

    Examples:
        >>> prime_factors(84)
        {2: 2, 3: 1, 7: 1}
        >>> prime_factors(1)
        {}
    """
    if n < 1:
        raise ValueError("n must be a positive integer")
    out: Dict[int, int] = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out

from math import gcd

def carmichael_lambda(n: int) -> int:
    """Return the Carmichael lambda of n.

    Args:
        n: A positive integer.

    Returns:
        The Carmichael value lambda(n).

    Examples:
        >>> carmichael_lambda(8)
        2
        >>> carmichael_lambda(15)
        4
    """
    if n < 1:
        raise ValueError("n must be positive")
    if n == 1:
        return 1
    factors = prime_factors(n)
    lambdas = []
    for p, e in factors.items():
        if p == 2:
            if e <= 2:
                lam = 1 if e == 1 else 2
            else:
                lam = 1 << (e - 2)
        else:
            lam = (p - 1) * (p ** (e - 1))
        lambdas.append(lam)
    return _lcm_list_int(lambdas)

def _lcm_list_int(ns):
    result = 1
    for x in ns:
        result = result * x // gcd(result, x)
    return result

from typing import Tuple

def generate_rsa_keypair(p: int, q: int, e: int = 65537) -> Tuple[int, int, int]:
    """Return (n, e, d) for a toy RSA keypair.

    Args:
        p: A prime.
        q: A different prime.
        e: Public exponent, coprime with phi(n).

    Returns:
        (n, e, d) where n = p*q.

    Examples:
        >>> n, e, d = generate_rsa_keypair(61, 53)
        >>> n
        3233
    """
    if p == q:
        raise ValueError("p and q must differ")
    n = p * q
    phi = (p - 1) * (q - 1)
    if _gcd(e, phi) != 1:
        raise ValueError("e must be coprime with phi(n)")
    d = mod_inverse(e, phi)
    if d is None:
        raise ValueError("no modular inverse")
    return n, e, d

def rsa_encrypt(m: int, e: int, n: int) -> int:
    """Encrypt integer message m with exponent e mod n."""
    if not 0 <= m < n:
        raise ValueError("m must be in [0, n)")
    return mod_pow(m, e, n)

def rsa_decrypt(c: int, d: int, n: int) -> int:
    """Decrypt ciphertext c with private exponent d mod n."""
    return mod_pow(c, d, n)

def _gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

