from math import gcd
from typing import Union

Number = Union[int, "Fraction"]

@dataclass(frozen=True)
class Fraction:
    """An immutable reduced rational number.

    Examples:
        >>> Fraction(1, 2) + Fraction(1, 3)
        Fraction(5, 6)
        >>> Fraction(2, 4) == Fraction(1, 2)
        True
    """
    num: int
    den: int

    def __post_init__(self) -> None:
        if self.den == 0:
            raise ZeroDivisionError("denominator must be non-zero")
        if self.den < 0:
            object.__setattr__(self, "num", -self.num)
            object.__setattr__(self, "den", -self.den)
        g = gcd(abs(self.num), abs(self.den))
        if g:
            object.__setattr__(self, "num", self.num // g)
            object.__setattr__(self, "den", self.den // g)

    def _to_pair(other: Number) -> tuple:
        if isinstance(other, Fraction):
            return other.num, other.den
        return int(other), 1

    def __add__(self, other: Number) -> "Fraction":
        a, b = Fraction._to_pair(other)
        return Fraction(self.num * b + a * self.den, self.den * b)

    def __sub__(self, other: Number) -> "Fraction":
        a, b = Fraction._to_pair(other)
        return Fraction(self.num * b - a * self.den, self.den * b)

    def __mul__(self, other: Number) -> "Fraction":
        a, b = Fraction._to_pair(other)
        return Fraction(self.num * a, self.den * b)

    def __truediv__(self, other: Number) -> "Fraction":
        a, b = Fraction._to_pair(other)
        if a == 0:
            raise ZeroDivisionError("division by zero")
        return Fraction(self.num * b, self.den * a)

import functools
from typing import Callable

@functools.lru_cache(maxsize=None)
def fib_cached(n: int) -> int:
    """Return the n-th Fibonacci number with memoization.

    Args:
        n: Non-negative integer.

    Returns:
        The n-th Fibonacci number.

    Examples:
        >>> fib_cached(10)
        55
        >>> fib_cached(20)
        6765
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n
    return fib_cached(n - 1) + fib_cached(n - 2)

def clear_fib_cache(func: Callable[..., int] = fib_cached) -> None:
    """Clear the lru_cache of fib_cached."""
    func.cache_clear()

from typing import Iterator, List

def miller_rabin(n: int, bases: List[int]) -> bool:
    """Return True if n passes Miller-Rabin for every base."""
    if n < 2:
        return False
    for p in (2, 3, 5, 7, 11, 13):
        if n % p == 0:
            return n == p
    d = n - 1
    r = 0
    while d % 2 == 0:
        d //= 2
        r += 1
    for a in bases:
        a %= n
        if a == 0:
            continue
        x = mod_pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(r - 1):
            x = mod_pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True

def filter_probable_primes(nums: Iterator[int]) -> Iterator[int]:
    """Yield nums that pass Miller-Rabin with the fixed bases."""
    bases = [2, 3, 5, 7, 11]
    for n in nums:
        if miller_rabin(n, bases):
            yield n

import heapq

class RunningMedian:
    """Maintains the running median of a stream.

    Examples:
        >>> r = RunningMedian()
        >>> [r.add(x) for x in [1, 2, 3]]
        [1, 1.5, 2]
        >>> r.add(10)
        2.5
    """
    def __init__(self) -> None:
        self.lo: list = []  # max-heap (negated)
        self.hi: list = []  # min-heap

    def add(self, x: float) -> float:
        if not self.lo or x <= -self.lo[0]:
            heapq.heappush(self.lo, -x)
        else:
            heapq.heappush(self.hi, x)
        if len(self.lo) > len(self.hi) + 1:
            heapq.heappush(self.hi, -heapq.heappop(self.lo))
        elif len(self.hi) > len(self.lo):
            heapq.heappush(self.lo, -heapq.heappop(self.hi))
        return self.median()

    def median(self) -> float:
        if len(self.lo) > len(self.hi):
            return float(-self.lo[0])
        return (-self.lo[0] + self.hi[0]) / 2
